// ─── HELIX FORGE · genome, phenotype & inheritance ──────────────────────────
// Every creature carries paired alleles. Expressed form and stats are derived
// from the whole genome, so breeding two creatures reshapes body AND behaviour.

export const GENES = [
  { key: 'size',      label: 'Stature',        group: 'frame',  desc: 'Overall body mass' },
  { key: 'length',    label: 'Torso Length',   group: 'frame',  desc: 'Spine elongation' },
  { key: 'girth',     label: 'Torso Girth',    group: 'frame',  desc: 'Ribcage volume' },
  { key: 'neck',      label: 'Neck',           group: 'frame',  desc: 'Cervical reach' },
  { key: 'head',      label: 'Cranium',        group: 'frame',  desc: 'Skull size' },
  { key: 'snout',     label: 'Jaw Reach',      group: 'frame',  desc: 'Bite projection' },
  { key: 'legs',      label: 'Limb Length',    group: 'limb',   desc: 'Stride length' },
  { key: 'stance',    label: 'Limb Build',     group: 'limb',   desc: 'Bone thickness' },
  { key: 'horns',     label: 'Cranial Horns',  group: 'weapon', desc: 'Gore potential' },
  { key: 'tail',      label: 'Caudal Tail',    group: 'weapon', desc: 'Balance & sweep' },
  { key: 'armor',     label: 'Dermal Plates',  group: 'weapon', desc: 'Spine spikes & scutes' },
  { key: 'wings',     label: 'Wing Membrane',  group: 'weapon', desc: 'Glide & gust' },
  { key: 'muscle',    label: 'Myofiber',       group: 'core',   desc: 'Raw contractile power' },
  { key: 'bone',      label: 'Bone Density',   group: 'core',   desc: 'Impact absorption' },
  { key: 'speed',     label: 'Fast Twitch',    group: 'core',   desc: 'Reaction & footspeed' },
  { key: 'brain',     label: 'Neural Mass',    group: 'core',   desc: 'Tactics & learning' },
  { key: 'metabolism',label: 'Metabolism',     group: 'core',   desc: 'Appetite & recovery' },
  { key: 'eyes',      label: 'Photoreceptors', group: 'core',   desc: 'Accuracy & threat read' },
  { key: 'hueA',      label: 'Pigment A',      group: 'coat',   desc: 'Primary chromatophore' },
  { key: 'hueB',      label: 'Pigment B',      group: 'coat',   desc: 'Secondary chromatophore' },
  { key: 'pattern',   label: 'Dermal Pattern', group: 'coat',   desc: 'Bands, spots, dapple' },
]

export const GENE_MAP = Object.fromEntries(GENES.map(g => [g.key, g]))

const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v))
export const clamp01 = v => clamp(v)
export const lerp = (a, b, t) => a + (b - a) * t
export const mix = (a, b, t) => Math.round(a + (b - a) * t)

export function mulberry32(seed) {
  let a = seed >>> 0
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const rnd = (min, max) => min + Math.random() * (max - min)

// ─── genome creation ───────────────────────────────────────────────────────
export function randomGenome(seed, bias = {}) {
  const r = seed == null ? Math.random : mulberry32(seed)
  const genome = {}
  for (const gene of GENES) {
    const b = bias[gene.key] ?? 0.5
    const spread = bias[gene.key + '_spread'] ?? 0.34
    const center = clamp(b + (r() - 0.5) * spread, 0.06, 0.96)
    const alleleA = clamp(center + (r() - 0.5) * 0.3, 0.02, 0.98)
    const alleleB = clamp(center + (r() - 0.5) * 0.3, 0.02, 0.98)
    // Hue genes are stored as full-range values, not centred on 0.5
    if (gene.key === 'hueA' || gene.key === 'hueB') {
      genome[gene.key] = bias[gene.key] != null
        ? [clamp(b + (r() - 0.5) * 0.18), clamp(b + (r() - 0.5) * 0.18)]
        : [r(), r()]
    } else {
      genome[gene.key] = [alleleA, alleleB]
    }
  }
  return genome
}

// Phenotype: average expression; a few genes skew dominant to create variety.
export function phenotype(genome) {
  const p = {}
  for (const gene of GENES) {
    const [a, b] = genome[gene.key]
    p[gene.key] = (a + b) / 2
  }
  // Derived composite values used by the mesh builder.
  const size = p.size
  p.height = 0.72 + size * 0.62 + p.legs * 0.18
  p.huePrimary = Math.round(lerp(18, 172, p.hueA) + 30)
  p.hueAccent = Math.round(lerp(2, 318, p.hueB))
  p.sat = Math.round(38 + p.pattern * 34 + p.muscle * 10)
  p.lightness = Math.round(52 - p.bone * 12 + p.eyes * 4)
  p.bodyColor = `hsl(${p.huePrimary} ${p.sat}% ${p.lightness}%)`
  p.accentColor = `hsl(${p.hueAccent} ${Math.min(92, p.sat + 18)}% ${58 + p.eyes * 8}%)`
  p.darkColor = `hsl(${p.huePrimary - 12} ${p.sat + 6}% ${Math.max(18, p.lightness - 26)}%)`
  p.eyeColor = `hsl(${(p.hueAccent + 38) % 360} 100% ${62 + p.brain * 10}%)`
  p.horniness = p.horns
  p.limbCount = 4
  return p
}

// ─── stats ─────────────────────────────────────────────────────────────────
export const STAT_KEYS = ['power', 'bones', 'mobility', 'muscle', 'brain', 'condition']
export const STAT_META = {
  power:    { label: 'Ability',  color: '#d8ff5f', short: 'PWR' },
  bones:    { label: 'Bones',    color: '#ffd36e', short: 'BON' },
  mobility: { label: 'Mobility', color: '#67e8f9', short: 'MOB' },
  muscle:   { label: 'Muscle',   color: '#ff8a7a', short: 'MUS' },
  brain:    { label: 'Brain',    color: '#c4a7ff', short: 'BRN' },
  condition:{ label: 'Condition',color: '#8fffc0', short: 'CON' },
}

export function averageNeeds(needs) {
  return (needs.hunger + needs.energy + needs.hygiene + needs.fun) / 4
}

export function heterozygosity(genome) {
  let sum = 0
  for (const gene of GENES) {
    const [a, b] = genome[gene.key]
    sum += Math.abs(a - b)
  }
  return sum / GENES.length
}

export function conditionOf(creature) {
  if (!creature) return 0
  const needs = creature.needs
  const vitality = averageNeeds(needs)
  const vigor = clamp01(heterozygosity(creature.genome) * 1.8) * 9
  const levelBonus = Math.min(6, (creature.wins || 0) * 0.8)
  const raw = vitality * 0.88 + vigor + levelBonus + 4
  return Math.round(clamp(raw, 4, 100))
}

export function statsOf(creature) {
  const p = phenotype(creature.genome)
  const cond = conditionOf(creature)
  const condMul = 0.72 + (cond / 100) * 0.28
  const raw = {
    power: 12 + p.size * 18 + p.muscle * 30 + p.bone * 14 + p.horns * 12 + p.snout * 6 + p.armor * 7,
    bones: 8 + p.bone * 84 + p.armor * 8,
    mobility: 8 + p.legs * 25 + p.speed * 32 + (1 - p.stance) * 12 + p.wings * 14 - p.size * 7,
    muscle: 6 + p.muscle * 88 + p.stance * 6,
    brain: 5 + p.brain * 88 + p.eyes * 7,
    condition: cond,
  }
  const out = {}
  for (const k of STAT_KEYS) out[k] = Math.round(clamp(k === 'condition' ? raw[k] : raw[k] * condMul, 3, 100))
  return out
}

export function maxHpOf(creature) {
  const p = phenotype(creature.genome)
  const stats = statsOf(creature)
  return Math.round(64 + p.size * 58 + p.bone * 34 + stats.muscle * 0.28 + p.armor * 16 + (creature.wins || 0) * 3)
}

export function maxStaminaOf(creature) {
  const p = phenotype(creature.genome)
  return Math.round(58 + p.speed * 34 + p.legs * 18 + p.brain * 10 + p.wings * 10)
}

export function needsProfile(creature) {
  const p = phenotype(creature.genome)
  return {
    hunger: 0.24 + p.metabolism * 0.33 + p.size * 0.13,
    energy: 0.10 + p.speed * 0.12 + p.size * 0.06 + p.wings * 0.05,
    hygiene: 0.05 + p.armor * 0.04 + p.pattern * 0.05,
    fun: 0.07 + p.brain * 0.15 + p.speed * 0.04,
  }
}

export function decayNeeds(creature, seconds) {
  const rate = needsProfile(creature)
  for (const k of ['hunger', 'energy', 'hygiene', 'fun']) {
    creature.needs[k] = Math.max(0, Math.min(100, creature.needs[k] - rate[k] * seconds))
  }
}

export function freshNeeds(value = 82) {
  return { hunger: value, energy: value, hygiene: value, fun: value }
}

// ─── movement / battle traits ──────────────────────────────────────────────
export function movesFor(creature) {
  const p = phenotype(creature.genome)
  const moves = []
  moves.push({
    id: 'bite', name: 'Rend', icon: '⚔', type: 'strike', cost: 11,
    power: 0.92 + p.snout * 0.38 + p.head * 0.14,
    acc: 0.88 + p.eyes * 0.08, tag: 'JAW',
    desc: 'A snapping bite. Reliable and cheap.',
    fx: 'bite',
  })
  if (p.horns > 0.18) moves.push({
    id: 'gore', name: 'Horn Rush', icon: '⛏', type: 'strike', cost: 18,
    power: 1.08 + p.horns * 0.52 + p.bone * 0.25,
    acc: 0.76 + p.speed * 0.15 + p.eyes * 0.06, tag: 'HORN',
    desc: 'Lower the crown and charge. Huge damage, less accurate.',
    fx: 'gore', crit: 0.1 + p.horns * 0.14,
  })
  if (p.armor > 0.2 || p.size > 0.55) moves.push({
    id: 'slam', name: 'Mass Slam', icon: '⬤', type: 'strike', cost: 16,
    power: 0.95 + p.size * 0.34 + p.muscle * 0.26 + p.armor * 0.14,
    acc: 0.82 + p.eyes * 0.06, tag: 'BODY',
    desc: 'Throw the whole mass forward. Shakes the arena.',
    fx: 'slam', stagger: 0.3,
  })
  if (p.tail > 0.3) moves.push({
    id: 'tail', name: 'Tail Sweep', icon: '↻', type: 'strike', cost: 12,
    power: 0.7 + p.tail * 0.44 + p.speed * 0.14,
    acc: 0.9, tag: 'TAIL',
    desc: 'A wide arc that leaves the foe off balance.',
    fx: 'tail', debuff: 'acc',
  })
  if (p.wings > 0.42) moves.push({
    id: 'gust', name: 'Wing Gust', icon: '≋', type: 'strike', cost: 14,
    power: 0.62 + p.wings * 0.42 + p.speed * 0.12,
    acc: 0.95, tag: 'WING',
    desc: 'Batter with a downdraft and lift your guard.',
    fx: 'gust', buff: 'evade',
  })
  if (p.brain > 0.55) moves.push({
    id: 'mind', name: 'Neural Lash', icon: '✦', type: 'strike', cost: 20,
    power: 0.86 + p.brain * 0.4 + p.eyes * 0.2,
    acc: 0.97, tag: 'MIND',
    desc: 'A focused psychic jab that pierces guarding.',
    fx: 'mind', pierce: true,
  })
  moves.push({
    id: 'guard', name: 'Brace', icon: '◈', type: 'defend', cost: -14,
    tag: 'GUARD', desc: 'Plant your feet. Halve the next hit, recover stamina.',
    fx: 'guard',
  })
  return moves.slice(0, 6)
}

// ─── breeding ──────────────────────────────────────────────────────────────
export function geneticSimilarity(a, b) {
  let sum = 0
  for (const gene of GENES) {
    const pa = (a[gene.key][0] + a[gene.key][1]) / 2
    const pb = (b[gene.key][0] + b[gene.key][1]) / 2
    sum += Math.abs(pa - pb)
  }
  return clamp01(1 - sum / GENES.length)
}

export function breedGenomes(genomeA, genomeB, mutationRate = 0.09) {
  const child = {}
  const mutations = []
  for (const gene of GENES) {
    const pickA = Math.random() < 0.5 ? genomeA[gene.key][0] : genomeA[gene.key][1]
    const pickB = Math.random() < 0.5 ? genomeB[gene.key][0] : genomeB[gene.key][1]
    let a = pickA, b = pickB
    if (Math.random() < mutationRate) {
      a = clamp(a + (Math.random() - 0.5) * 0.26)
      mutations.push(gene.key)
    }
    if (Math.random() < mutationRate) {
      b = clamp(b + (Math.random() - 0.5) * 0.26)
      if (!mutations.includes(gene.key)) mutations.push(gene.key)
    }
    child[gene.key] = [a, b]
  }
  return { genome: child, mutations: [...new Set(mutations)] }
}

const FIRST = ['Vex', 'Morrow', 'Thal', 'Kestrel', 'Nyra', 'Orin', 'Sable', 'Quill', 'Rime', 'Ash', 'Bramble', 'Cinder', 'Dusk', 'Echo', 'Fen', 'Gloam', 'Harrow', 'Iris', 'Juno', 'Kite', 'Lumen', 'Moss', 'Nettle', 'Onyx', 'Pyre', 'Rook', 'Silt', 'Thorn', 'Umber', 'Vale', 'Wisp', 'Yarrow', 'Zephyr', 'Cobalt', 'Dune', 'Ember', 'Flint', 'Gale', 'Hazel', 'Indigo', 'Jasper', 'Kelp', 'Lark', 'Mica', 'Nimbus', 'Opal', 'Pearl', 'Reed', 'Slate', 'Tide']
const SECOND = ['back', 'wing', 'maw', 'horn', 'crest', 'shade', 'spine', 'bloom', 'stride', 'gaze', 'fang', 'scale', 'song', 'tread', 'vault', 'whisper', 'cradle', 'howl', 'drift', 'spark']

export function makeName(genome, parents) {
  const p = phenotype(genome)
  const first = FIRST[Math.floor(Math.random() * FIRST.length)]
  let epithet = SECOND[Math.floor(Math.random() * SECOND.length)]
  if (p.horns > 0.65) epithet = 'horn'
  else if (p.wings > 0.6) epithet = 'wing'
  else if (p.brain > 0.7) epithet = 'gaze'
  else if (p.speed > 0.68) epithet = 'stride'
  else if (p.armor > 0.65) epithet = 'scale'
  const name = `${first}${epithet}`
  return name.charAt(0).toUpperCase() + name.slice(1)
}

export function sexOf() {
  return Math.random() < 0.5 ? 'F' : 'M'
}

export function generateStarter(seed, bias) {
  const genome = randomGenome(seed, bias)
  return {
    id: cryptoId(),
    name: makeName(genome),
    genome,
    sex: seed % 2 === 0 ? 'F' : 'M',
    needs: freshNeeds(86),
    wins: 0,
    battles: 0,
    born: Date.now(),
    generation: 0,
  }
}

let idCounter = 0
export function cryptoId() {
  idCounter++
  return 'c' + Date.now().toString(36) + idCounter.toString(36) + Math.random().toString(36).slice(2, 5)
}

export function dnaSequence(genome) {
  const bases = 'ACGT'
  let seq = ''
  for (const gene of GENES) {
    for (const allele of genome[gene.key]) {
      const n = Math.floor(allele * 4095)
      for (let i = 0; i < 3; i++) seq += bases[(n >> (i * 2)) & 3]
    }
    seq += '·'
  }
  return seq.slice(0, -1)
}

export function formatAge(born) {
  const s = Math.max(0, (Date.now() - born) / 1000)
  if (s < 90) return `${Math.floor(s)}s`
  if (s < 5400) return `${Math.floor(s / 60)}m`
  if (s < 86400 * 2) return `${Math.floor(s / 3600)}h`
  return `${Math.floor(s / 86400)}d`
}

import * as THREE from 'three'
import { phenotype } from './dna.js'

// ─── materials & procedural coat texture ───────────────────────────────────
const texCache = new Map()

function hashString(str) {
  let h = 2166136261
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619) }
  return h >>> 0
}

function rng(seed) {
  let a = seed >>> 0
  return () => {
    a |= 0; a = (a + 0x6D2B79F5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function coatTexture(p, key) {
  const cacheKey = `${p.bodyColor}|${p.darkColor}|${p.accentColor}|${p.pattern.toFixed(2)}|${key}`
  if (texCache.has(cacheKey)) return texCache.get(cacheKey)
  const size = 256
  const canvas = document.createElement('canvas')
  canvas.width = canvas.height = size
  const ctx = canvas.getContext('2d')
  const r = rng(hashString(cacheKey))
  ctx.fillStyle = p.bodyColor
  ctx.fillRect(0, 0, size, size)

  // soft mottling
  for (let i = 0; i < 90; i++) {
    const x = r() * size, y = r() * size, rad = 6 + r() * 26
    ctx.globalAlpha = 0.05 + r() * 0.1
    ctx.fillStyle = r() > 0.5 ? p.darkColor : p.accentColor
    ctx.beginPath(); ctx.ellipse(x, y, rad, rad * (0.4 + r()), r() * Math.PI, 0, Math.PI * 2); ctx.fill()
  }
  ctx.globalAlpha = 1

  const mode = p.pattern < 0.34 ? 'spots' : p.pattern < 0.68 ? 'bands' : 'dapple'
  ctx.fillStyle = p.darkColor
  if (mode === 'spots') {
    ctx.globalAlpha = 0.5
    for (let i = 0; i < 34; i++) {
      const x = r() * size, y = r() * size, rad = 3 + r() * 8
      ctx.beginPath(); ctx.arc(x, y, rad, 0, Math.PI * 2); ctx.fill()
    }
    ctx.globalAlpha = 0.3
    ctx.fillStyle = p.accentColor
    for (let i = 0; i < 16; i++) {
      ctx.beginPath(); ctx.arc(r() * size, r() * size, 1.5 + r() * 3, 0, Math.PI * 2); ctx.fill()
    }
  } else if (mode === 'bands') {
    ctx.globalAlpha = 0.4
    for (let i = 0; i < 6; i++) {
      const y = i * 44 + 10 + r() * 8
      ctx.beginPath(); ctx.moveTo(0, y)
      ctx.bezierCurveTo(70, y - 12, 170, y + 12, size, y - 4)
      ctx.lineTo(size, y + 12 + r() * 8)
      ctx.bezierCurveTo(170, y + 24, 70, y + 2, 0, y + 18)
      ctx.closePath(); ctx.fill()
    }
    ctx.globalAlpha = 0.25
    ctx.fillStyle = p.accentColor
    for (let i = 0; i < 5; i++) {
      const y = i * 52 + 30
      ctx.fillRect(0, y, size, 2)
    }
  } else {
    ctx.globalAlpha = 0.36
    for (let i = 0; i < 70; i++) {
      const x = r() * size, y = r() * size, rad = 4 + r() * 14
      ctx.beginPath(); ctx.arc(x, y, rad, 0, Math.PI * 2); ctx.fill()
    }
    ctx.globalAlpha = 0.3
    ctx.fillStyle = p.accentColor
    for (let i = 0; i < 26; i++) {
      ctx.beginPath(); ctx.arc(r() * size, r() * size, 1 + r() * 2.5, 0, Math.PI * 2); ctx.fill()
    }
  }
  ctx.globalAlpha = 0.18
  for (let i = 0; i < 800; i++) {
    ctx.fillStyle = r() > 0.5 ? '#ffffff' : '#000000'
    ctx.fillRect(r() * size, r() * size, 1, 1)
  }
  ctx.globalAlpha = 1
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.anisotropy = 4
  texCache.set(cacheKey, tex)
  if (texCache.size > 100) {
    const first = texCache.keys().next().value
    texCache.get(first)?.dispose()
    texCache.delete(first)
  }
  return tex
}

function mat(color, opts = {}) {
  return new THREE.MeshStandardMaterial({
    color,
    roughness: opts.roughness ?? 0.72,
    metalness: opts.metalness ?? 0.04,
    flatShading: opts.flat ?? false,
    emissive: opts.emissive ?? 0x000000,
    emissiveIntensity: opts.emissiveIntensity ?? 1,
    transparent: opts.transparent ?? false,
    opacity: opts.opacity ?? 1,
    side: opts.side ?? THREE.FrontSide,
    map: opts.map,
  })
}

function addMesh(parent, geo, material, pos = [0, 0, 0], rot = [0, 0, 0], scl = [1, 1, 1]) {
  const m = new THREE.Mesh(geo, material)
  m.position.set(...pos)
  m.rotation.set(...rot)
  m.scale.set(...scl)
  m.castShadow = true
  m.receiveShadow = true
  parent.add(m)
  return m
}

// ─── creature mesh ─────────────────────────────────────────────────────────
export function buildCreature(genome, opts = {}) {
  const p = phenotype(genome)
  const root = new THREE.Group()
  const model = new THREE.Group()
  root.add(model)

  const s = 0.78 + p.size * 0.52
  const torsoRY = (0.5 + p.girth * 0.3) * s
  const torsoRX = (0.52 + p.girth * 0.48) * s
  const torsoRZ = (0.62 + p.length * 0.55) * s
  const legLen = (0.34 + p.legs * 0.62) * s
  const legThick = 0.09 + p.stance * 0.12
  const hipY = legLen + torsoRY * 0.42
  const headScale = (0.34 + p.head * 0.36) * s
  const bodyY = legLen + torsoRY * 0.55

  const coat = coatTexture(p, 'body')
  const bodyMat = mat(0xffffff, { map: coat, roughness: 0.66 })
  const darkMat = mat(p.darkColor, { roughness: 0.8 })
  const accentMat = mat(p.accentColor, { roughness: 0.55, metalness: 0.12 })
  const boneMat = mat('#e8dfc4', { roughness: 0.62, flat: true })
  const clawMat = mat('#332f27', { roughness: 0.4, metalness: 0.2 })
  const eyeMat = mat(p.eyeColor, { emissive: p.eyeColor, emissiveIntensity: 2.1, roughness: 0.2 })
  const pupilMat = mat('#0a0d0c', { roughness: 0.3 })
  const wingMat = mat(p.accentColor, { transparent: true, opacity: 0.72, side: THREE.DoubleSide, roughness: 0.5, emissive: p.darkColor, emissiveIntensity: 0.16 })

  const bodyGroup = new THREE.Group()
  bodyGroup.position.y = bodyY
  model.add(bodyGroup)

  const torsoGeo = new THREE.IcosahedronGeometry(1, 2)
  const torso = addMesh(bodyGroup, torsoGeo, bodyMat, [0, 0, 0], [0, 0, 0], [torsoRX, torsoRY, torsoRZ])
  // belly plate
  addMesh(bodyGroup, new THREE.IcosahedronGeometry(1, 1), mat(p.accentColor, { roughness: 0.7 }), [0, -torsoRY * 0.55, torsoRZ * 0.05], [0, 0, 0], [torsoRX * 0.8, torsoRY * 0.42, torsoRZ * 0.86])

  // ── neck & head ──
  const neckBase = new THREE.Group()
  neckBase.position.set(0, torsoRY * 0.3, torsoRZ * 0.62)
  bodyGroup.add(neckBase)
  const neckLen = (0.16 + p.neck * 0.62) * s
  const neckGeo = new THREE.CapsuleGeometry(0.17 * s, neckLen, 3, 8)
  addMesh(neckBase, neckGeo, bodyMat, [0, neckLen * 0.34, 0.06 * s], [-0.62 + p.neck * 0.2, 0, 0], [1, 1, 1.05 + p.neck * 0.3])

  const headGroup = new THREE.Group()
  headGroup.position.set(0, neckLen * 0.82 + 0.06 * s, neckLen * 0.48)
  neckBase.add(headGroup)
  const skull = addMesh(headGroup, new THREE.IcosahedronGeometry(1, 2), bodyMat, [0, 0, 0], [0, 0, 0], [headScale, headScale * 0.82, headScale * 1.02])
  // jaw / snout
  const snoutLen = headScale * (0.72 + p.snout * 0.78)
  addMesh(headGroup, new THREE.CapsuleGeometry(headScale * 0.41, snoutLen, 3, 8), darkMat,
    [0, -headScale * 0.18, headScale * 0.62 + snoutLen * 0.34], [Math.PI / 2, 0, 0], [1, 1, 0.8])
  addMesh(headGroup, new THREE.CapsuleGeometry(headScale * 0.3, snoutLen * 0.68, 3, 8), bodyMat,
    [0, -headScale * 0.38, headScale * 0.7 + snoutLen * 0.24], [Math.PI / 2, 0, 0], [1, 1, 0.6])
  // teeth
  const toothGeo = new THREE.ConeGeometry(headScale * 0.055, headScale * 0.19, 4)
  for (let i = 0; i < 4; i++) {
    addMesh(headGroup, toothGeo, boneMat, [(i - 1.5) * headScale * 0.16, -headScale * 0.48, headScale * 0.72 + snoutLen * 0.4 + (i % 2) * 0.02], [Math.PI, 0, 0])
  }
  // eyes
  const eyeR = headScale * (0.13 + p.eyes * 0.1)
  for (const side of [-1, 1]) {
    const ex = side * headScale * 0.58, ey = headScale * 0.16, ez = headScale * 0.62
    addMesh(headGroup, new THREE.SphereGeometry(eyeR, 14, 10), eyeMat, [ex, ey, ez], [0, 0, 0], [1, 1, 0.7])
    addMesh(headGroup, new THREE.SphereGeometry(eyeR * 0.48, 10, 8), pupilMat, [ex + side * eyeR * 0.35, ey, ez + eyeR * 0.5], [0, 0, 0], [1, 1, 0.5])
  }
  // brow ridge
  addMesh(headGroup, new THREE.BoxGeometry(headScale * 0.95, headScale * 0.16, headScale * 0.34), darkMat, [0, headScale * 0.36, headScale * 0.5], [0.18, 0, 0])

  // horns
  const hornPairs = p.horns > 0.74 ? 3 : p.horns > 0.46 ? 2 : p.horns > 0.16 ? 1 : 0
  for (let pair = 0; pair < hornPairs; pair++) {
    for (const side of [-1, 1]) {
      const len = headScale * (0.55 + p.horns * 1.15) * (1 - pair * 0.22)
      const horn = addMesh(headGroup, new THREE.ConeGeometry(headScale * 0.14, len, 6), boneMat,
        [side * (headScale * 0.34 + pair * headScale * 0.12), headScale * 0.6 + pair * headScale * 0.15, headScale * (0.18 - pair * 0.24)],
        [-0.35, 0, side * -(0.25 + pair * 0.2)], [1, 1, 1])
      horn.castShadow = true
    }
  }
  // crest / ear fins
  if (p.wings > 0.3) {
    for (const side of [-1, 1]) {
      const fin = addMesh(headGroup, new THREE.ConeGeometry(headScale * 0.26, headScale * 0.7, 4), wingMat,
        [side * headScale * 0.7, headScale * 0.15, -headScale * 0.15], [0, 0, side * -1.15], [1, 0.3, 1])
      fin.material = wingMat
    }
  }

  // ── back spikes ──
  if (p.armor > 0.2) {
    const count = 2 + Math.floor(p.armor * 7)
    for (let i = 0; i < count; i++) {
      const t = i / (count - 1 || 1)
      const h = torsoRY * (1.05 - t * 0.5) * (0.55 + p.armor * 0.55)
      const spike = addMesh(bodyGroup, new THREE.ConeGeometry(torsoRX * 0.16, h, 4), boneMat,
        [0, torsoRY * (0.72 - Math.abs(t - 0.4) * 0.5), torsoRZ * (0.62 - t * 1.25)],
        [-0.24, 0, 0], [1, 1, 1])
      spike.castShadow = true
    }
  }
  // shoulder scutes
  for (const side of [-1, 1]) {
    addMesh(bodyGroup, new THREE.IcosahedronGeometry(1, 0), darkMat,
      [side * torsoRX * 0.72, torsoRY * 0.34, torsoRZ * 0.3], [0, 0, side * 0.4], [torsoRX * 0.26, torsoRY * 0.2, torsoRZ * 0.42])
  }

  // ── tail ──
  const tailSegs = []
  if (p.tail > 0.08) {
    let parent = new THREE.Group()
    parent.position.set(0, torsoRY * 0.12, -torsoRZ * 0.92)
    bodyGroup.add(parent)
    const segCount = 4
    for (let i = 0; i < segCount; i++) {
      const seg = new THREE.Group()
      const r = (0.2 - i * 0.032) * s * (0.7 + p.tail * 0.7)
      const len = (0.32 + p.tail * 0.42) * s
      seg.position.z = i === 0 ? 0 : -len * 0.92
      const g = new THREE.CapsuleGeometry(Math.max(0.045, r), len, 2, 7)
      addMesh(seg, g, i % 2 === 0 ? bodyMat : darkMat, [0, 0, -len * 0.46], [Math.PI / 2, 0, 0])
      parent.add(seg)
      tailSegs.push(seg)
      parent = seg
      if (i === segCount - 1 && p.armor > 0.3) {
        addMesh(seg, new THREE.ConeGeometry(r * 1.2, len * 1.1, 5), boneMat, [0, 0, -len * 1.1], [-Math.PI / 2, 0, 0])
      }
    }
  }

  // ── wings ──
  const wings = []
  if (p.wings > 0.42) {
    const wingGroup = new THREE.Group()
    wingGroup.position.set(0, torsoRY * 0.5, torsoRZ * 0.05)
    bodyGroup.add(wingGroup)
    const span = (0.9 + p.wings * 1.35) * s
    const height = (0.6 + p.wings * 0.9) * s
    const shape = new THREE.Shape()
    shape.moveTo(0, 0)
    shape.quadraticCurveTo(span * 0.55, height * 0.7, span, height * 0.18)
    shape.quadraticCurveTo(span * 0.7, -height * 0.12, span * 0.38, -height * 0.28)
    shape.quadraticCurveTo(span * 0.22, -height * 0.08, 0, 0)
    const wingGeo = new THREE.ShapeGeometry(shape, 12)
    for (const side of [-1, 1]) {
      const pivot = new THREE.Group()
      pivot.rotation.z = side * 0.18
      wingGroup.add(pivot)
      const w = new THREE.Mesh(wingGeo, wingMat)
      w.scale.x = side
      w.castShadow = true
      pivot.add(w)
      // leading edge strut
      const bone = new THREE.Mesh(new THREE.CylinderGeometry(0.028 * s, 0.045 * s, span, 5), darkMat)
      bone.position.set(side * span * 0.46, height * 0.22, 0)
      bone.rotation.z = side * -0.42
      bone.castShadow = true
      wingGroup.add(bone)
      wings.push(pivot)
    }
  }

  // ── legs ──
  const legs = []
  const hips = [
    { x: -1, z: 0.48, front: true },
    { x: 1, z: 0.48, front: true },
    { x: -1, z: -0.5, front: false },
    { x: 1, z: -0.5, front: false },
  ]
  for (const hip of hips) {
    const leg = new THREE.Group()
    leg.position.set(hip.x * torsoRX * 0.62, hipY, hip.z * torsoRZ * 0.86)
    const scaleLeg = (hip.front ? 0.86 : 1) * (0.8 + p.legs * 0.34)
    const upper = legLen * 0.52 * scaleLeg
    const lower = legLen * 0.54 * scaleLeg
    const thick = legThick * (hip.front ? 0.84 : 1.1)
    addMesh(leg, new THREE.CapsuleGeometry(thick, upper, 2, 7), bodyMat, [0, -upper * 0.5, 0], [0, 0, 0], [1, 1, 1])
    const knee = new THREE.Group()
    knee.position.y = -upper
    leg.add(knee)
    addMesh(knee, new THREE.SphereGeometry(thick * 1.15, 8, 6), darkMat)
    addMesh(knee, new THREE.CapsuleGeometry(thick * 0.78, lower * 0.82, 2, 7), darkMat, [0, -lower * 0.45, 0])
    const foot = addMesh(knee, new THREE.IcosahedronGeometry(thick * 1.7, 1), darkMat, [0, -lower * 0.92, thick * 0.55], [0, 0, 0], [1.5, 0.55, 1.9])
    foot.castShadow = true
    // claws
    for (let c = -1; c <= 1; c++) {
      addMesh(knee, new THREE.ConeGeometry(thick * 0.3, thick * 1.15, 4), clawMat,
        [c * thick * 0.7, -lower * 0.94, thick * 1.4], [Math.PI / 2.2, 0, 0])
    }
    leg.rotation.x = hip.front ? 0.06 : -0.06
    legs.push({ group: leg, knee, front: hip.front, phase: hip.front ? (hip.x > 0 ? 0 : Math.PI) : (hip.x > 0 ? Math.PI : 0) })
    model.add(leg)
  }

  // ── ground fit ──
  model.updateMatrixWorld(true)
  const box = new THREE.Box3().setFromObject(model)
  const lift = -box.min.y
  model.position.y = lift + 0.015

  // animation state
  let t = Math.random() * 10
  let walkAmt = 0
  let flashTime = 0
  let flashColor = new THREE.Color('#ffffff')
  const materials = []
  root.traverse(o => { if (o.material && !materials.includes(o.material)) materials.push(o.material) })
  const baseEmissive = materials.map(m => ({ m, e: m.emissive ? m.emissive.clone() : null, i: m.emissiveIntensity }))

  function update(dt, movement = 0) {
    t += dt
    walkAmt += (movement - walkAmt) * Math.min(1, dt * 7)
    const breathe = Math.sin(t * 1.7) * 0.014
    bodyGroup.scale.set(1 + breathe * 0.4, 1 + breathe, 1 + breathe * 0.3)
    bodyGroup.position.y = bodyY + Math.sin(t * 1.7) * 0.012 + Math.abs(Math.cos(t * 6)) * 0.03 * walkAmt
    neckBase.rotation.x = Math.sin(t * 1.1) * 0.04 - 0.04 + walkAmt * 0.06
    headGroup.rotation.x = Math.sin(t * 1.4 + 0.7) * 0.05
    headGroup.rotation.y = Math.sin(t * 0.6) * 0.13
    headGroup.rotation.z = Math.sin(t * 0.9) * 0.02

    for (const seg of tailSegs) {
      seg.rotation.y = Math.sin(t * 1.6 + seg.id * 0.4) * 0.12 + Math.sin(t * 0.7) * 0.05
      seg.rotation.x = Math.sin(t * 1.2 + 0.6) * 0.035
    }
    for (let i = 0; i < wings.length; i++) {
      const side = i === 0 ? -1 : 1
      wings[i].rotation.z = side * (0.12 + Math.sin(t * 2.3) * 0.18) + side * walkAmt * 0.12
      wings[i].rotation.x = Math.sin(t * 1.5 + i) * 0.06
    }
    for (const leg of legs) {
      const phase = walkAmt > 0.02 ? Math.sin(t * 7.5 + leg.phase) : 0
      leg.group.rotation.x = (leg.front ? 0.06 : -0.06) + phase * 0.5 * walkAmt
      leg.knee.rotation.x = Math.max(0, -phase) * 0.6 * walkAmt
    }
    if (flashTime > 0) {
      flashTime -= dt
      const k = Math.max(0, flashTime / 0.18)
      for (const b of baseEmissive) {
        if (!b.e) continue
        b.m.emissive.copy(b.e).lerp(flashColor, k)
        b.m.emissiveIntensity = b.i + k * 2.4
      }
    }
  }

  function flash(color = '#ffffff', duration = 0.18) {
    flashColor.set(color)
    flashTime = duration
  }

  function dispose() {
    model.traverse(o => {
      if (o.geometry) o.geometry.dispose()
    })
    for (const m of materials) m.dispose()
    root.removeFromParent()
  }

  // store tail ids for animation phase
  tailSegs.forEach((seg, i) => { seg.id = i })

  root.userData = { update, flash, dispose, phenotype: p, materials }
  root.scale.setScalar(opts.scale ?? 1)
  root.name = 'creature'
  root.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true } })
  return root
}

// ─── portrait snapshot ─────────────────────────────────────────────────────
let portraitRenderer = null
export function portraitDataURL(genome, size = 220) {
  if (!portraitRenderer) {
    portraitRenderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, preserveDrawingBuffer: true })
    portraitRenderer.setPixelRatio(1)
    portraitRenderer.outputColorSpace = THREE.SRGBColorSpace
    portraitRenderer.toneMapping = THREE.ACESFilmicToneMapping
    portraitRenderer.toneMappingExposure = 1.1
    portraitRenderer.shadowMap.enabled = false
  }
  portraitRenderer.setSize(size, size, false)
  const scene = new THREE.Scene()
  const creature = buildCreature(genome)
  // face three-quarter
  creature.rotation.y = -0.5
  creature.update(0.2, 0)
  scene.add(creature)
  const box = new THREE.Box3().setFromObject(creature)
  const sphere = box.getBoundingSphere(new THREE.Sphere())
  const cam = new THREE.PerspectiveCamera(34, 1, 0.1, 100)
  const dist = sphere.radius / Math.sin((34 * Math.PI / 180) / 2) * 0.84
  cam.position.set(sphere.center.x + dist * 0.18, sphere.center.y + dist * 0.18, sphere.center.z + dist)
  cam.lookAt(sphere.center)
  scene.add(cam)
  scene.add(new THREE.HemisphereLight(0xcffcff, 0x203030, 2.2))
  const key = new THREE.DirectionalLight(0xfff3d6, 3.2)
  key.position.set(3, 5, 4)
  scene.add(key)
  const rim = new THREE.DirectionalLight(0x6fffd7, 2.2)
  rim.position.set(-4, 2, -3)
  scene.add(rim)
  portraitRenderer.render(scene, cam)
  const url = portraitRenderer.domElement.toDataURL('image/jpeg', 0.86)
  creature.userData.dispose()
  return url
}

import * as THREE from 'three'
import { buildCreature } from './creature.js'

const clamp = (v, a, b) => Math.max(a, Math.min(b, v))

function groundTexture(kind) {
  const c = document.createElement('canvas')
  c.width = c.height = 512
  const x = c.getContext('2d')
  if (kind === 'habitat') {
    const grad = x.createRadialGradient(256, 256, 20, 256, 256, 260)
    grad.addColorStop(0, '#274b44')
    grad.addColorStop(0.65, '#1c3a38')
    grad.addColorStop(1, '#12292c')
    x.fillStyle = grad
    x.fillRect(0, 0, 512, 512)
    for (let i = 0; i < 1200; i++) {
      x.globalAlpha = 0.05 + Math.random() * 0.12
      x.fillStyle = ['#5affc8', '#0e1e22', '#8de0a0', '#456c5c'][Math.floor(Math.random() * 4)]
      const r = 1 + Math.random() * 16
      x.beginPath(); x.arc(Math.random() * 512, Math.random() * 512, r, 0, Math.PI * 2); x.fill()
    }
    // faint mycelium veins
    x.globalAlpha = 0.26
    x.strokeStyle = '#68f7c3'
    x.lineWidth = 1.1
    for (let i = 0; i < 26; i++) {
      x.beginPath()
      let px = Math.random() * 512, py = Math.random() * 512
      x.moveTo(px, py)
      for (let s = 0; s < 5; s++) {
        px += (Math.random() - 0.5) * 90
        py += (Math.random() - 0.5) * 90
        x.lineTo(px, py)
      }
      x.stroke()
    }
    // rings
    x.globalAlpha = 0.22
    x.strokeStyle = '#7effd2'
    for (let r = 80; r < 250; r += 56) {
      x.lineWidth = r === 192 ? 2 : 1
      x.beginPath(); x.arc(256, 256, r, 0, Math.PI * 2); x.stroke()
    }
  } else {
    const grad = x.createRadialGradient(256, 256, 30, 256, 256, 260)
    grad.addColorStop(0, '#2a2430')
    grad.addColorStop(0.7, '#1b1a25')
    grad.addColorStop(1, '#100f18')
    x.fillStyle = grad
    x.fillRect(0, 0, 512, 512)
    for (let i = 0; i < 900; i++) {
      x.globalAlpha = 0.04 + Math.random() * 0.1
      x.fillStyle = ['#ff5e8a', '#ffb46b', '#14121c', '#5f4d66'][Math.floor(Math.random() * 4)]
      x.beginPath(); x.arc(Math.random() * 512, Math.random() * 512, 1 + Math.random() * 18, 0, Math.PI * 2); x.fill()
    }
    x.globalAlpha = 0.5
    x.strokeStyle = '#ff7a5c'
    x.lineWidth = 1.4
    for (let i = 0; i < 18; i++) {
      x.beginPath()
      let px = Math.random() * 512, py = Math.random() * 512
      x.moveTo(px, py)
      for (let s = 0; s < 6; s++) {
        px += (Math.random() - 0.5) * 70
        py += (Math.random() - 0.5) * 70
        x.lineTo(px, py)
      }
      x.stroke()
    }
    x.globalAlpha = 0.3
    x.strokeStyle = '#ffcf7a'
    for (let r = 70; r < 250; r += 60) {
      x.beginPath(); x.arc(256, 256, r, 0, Math.PI * 2); x.stroke()
    }
  }
  x.globalAlpha = 1
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

function skyMesh(top, horizon, bottom) {
  const geo = new THREE.SphereGeometry(90, 24, 16)
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    uniforms: {
      top: { value: new THREE.Color(top) },
      horizon: { value: new THREE.Color(horizon) },
      bottom: { value: new THREE.Color(bottom) },
    },
    vertexShader: `varying vec3 vP; void main(){ vP = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
    fragmentShader: `
      varying vec3 vP; uniform vec3 top; uniform vec3 horizon; uniform vec3 bottom;
      float hash(vec3 p){ return fract(sin(dot(p, vec3(12.9898,78.233,45.164)))*43758.5453); }
      void main(){
        vec3 d = normalize(vP);
        float h = d.y;
        vec3 col = mix(horizon, top, smoothstep(0.02, 0.65, h));
        col = mix(bottom, col, smoothstep(-0.35, 0.03, h));
        float star = step(0.9975, hash(floor(d*420.0))) * smoothstep(0.15, 0.5, h);
        col += vec3(0.55,0.9,0.8) * star * 0.85;
        gl_FragColor = vec4(col, 1.0);
      }`,
  })
  return new THREE.Mesh(geo, mat)
}

function sporeField(count, color, radius, height, size) {
  const positions = new Float32Array(count * 3)
  const seeds = []
  for (let i = 0; i < count; i++) {
    const a = Math.random() * Math.PI * 2
    const r = Math.sqrt(Math.random()) * radius
    const y = Math.random() * height
    positions[i * 3] = Math.cos(a) * r
    positions[i * 3 + 1] = y
    positions[i * 3 + 2] = Math.sin(a) * r
    seeds.push({ speed: 0.1 + Math.random() * 0.35, phase: Math.random() * 10, a })
  }
  const geo = new THREE.BufferGeometry()
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3))
  const mat = new THREE.PointsMaterial({ color, size, transparent: true, opacity: 0.8, depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true })
  const points = new THREE.Points(geo, mat)
  points.userData.seeds = seeds
  return points
}

function mushroom(x, z, scale, hue) {
  const g = new THREE.Group()
  const stemMat = new THREE.MeshStandardMaterial({ color: '#c9d8bd', roughness: 0.8 })
  const capMat = new THREE.MeshStandardMaterial({ color: hue, emissive: hue, emissiveIntensity: 0.5, roughness: 0.5 })
  const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.06 * scale, 0.1 * scale, 0.6 * scale, 6), stemMat)
  stem.position.y = 0.3 * scale
  stem.castShadow = true
  g.add(stem)
  const cap = new THREE.Mesh(new THREE.SphereGeometry(0.26 * scale, 10, 6, 0, Math.PI * 2, 0, Math.PI / 2), capMat)
  cap.position.y = 0.6 * scale
  cap.scale.y = 0.6
  cap.castShadow = true
  g.add(cap)
  const dotMat = new THREE.MeshBasicMaterial({ color: '#f4ffe0' })
  for (let i = 0; i < 4; i++) {
    const dot = new THREE.Mesh(new THREE.SphereGeometry(0.028 * scale, 5, 4), dotMat)
    const a = Math.random() * Math.PI * 2
    dot.position.set(Math.cos(a) * 0.16 * scale, 0.62 * scale + Math.random() * 0.05 * scale, Math.sin(a) * 0.16 * scale)
    g.add(dot)
  }
  g.position.set(x, 0, z)
  g.rotation.y = Math.random() * Math.PI
  return g
}

function crystal(x, z, scale, color) {
  const g = new THREE.Group()
  const m = new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 0.65, roughness: 0.25, metalness: 0.1, flatShading: true })
  for (let i = 0; i < 3; i++) {
    const h = (0.7 + Math.random() * 1.3) * scale
    const shard = new THREE.Mesh(new THREE.ConeGeometry((0.12 + Math.random() * 0.2) * scale, h, 5), m)
    shard.position.set((Math.random() - 0.5) * 0.5 * scale, h / 2, (Math.random() - 0.5) * 0.5 * scale)
    shard.rotation.z = (Math.random() - 0.5) * 0.4
    shard.rotation.x = (Math.random() - 0.5) * 0.3
    shard.castShadow = true
    g.add(shard)
  }
  g.position.set(x, 0, z)
  return g
}

function tree(x, z, scale, palette) {
  const g = new THREE.Group()
  const trunk = new THREE.Mesh(
    new THREE.CylinderGeometry(0.13 * scale, 0.24 * scale, 2.1 * scale, 6),
    new THREE.MeshStandardMaterial({ color: '#2b2a2e', roughness: 0.9 })
  )
  trunk.position.y = 1.05 * scale
  trunk.castShadow = true
  g.add(trunk)
  const canopyMat = new THREE.MeshStandardMaterial({ color: palette, roughness: 0.8, flatShading: true })
  for (let i = 0; i < 3; i++) {
    const c = new THREE.Mesh(new THREE.IcosahedronGeometry((0.65 + Math.random() * 0.3) * scale, 0), canopyMat)
    c.position.set((Math.random() - 0.5) * 0.7 * scale, (1.9 + Math.random() * 0.7) * scale, (Math.random() - 0.5) * 0.7 * scale)
    c.castShadow = true
    g.add(c)
  }
  const glow = new THREE.Mesh(new THREE.IcosahedronGeometry(0.09 * scale, 0), new THREE.MeshBasicMaterial({ color: '#b8ffd8' }))
  glow.position.set(0.3 * scale, 2.2 * scale, 0.4 * scale)
  g.add(glow)
  g.position.set(x, 0, z)
  g.rotation.y = Math.random() * Math.PI * 2
  return g
}

export class World {
  constructor(container, hooks = {}) {
    this.container = container
    this.hooks = hooks
    this.mode = 'habitat'
    this.creatures = new Map()
    this.selectedId = null
    this.time = 0
    this.shakeAmt = 0
    this.pointer = { down: false, x: 0, y: 0, moved: 0 }
    this.orbit = { yaw: 0.55, pitch: 0.34, radius: 10.5, targetY: 1.35 }
    this.autoRotate = true
    this.bindCamera = { yaw: 0, pitch: 0, radius: 11 }
    this.raycaster = new THREE.Raycaster()
    this.ndc = new THREE.Vector2()

    this.renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' })
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2))
    this.renderer.outputColorSpace = THREE.SRGBColorSpace
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping
    this.renderer.toneMappingExposure = 1.05
    this.renderer.shadowMap.enabled = true
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap
    this.renderer.domElement.style.display = 'block'
    this.renderer.domElement.style.touchAction = 'none'
    container.appendChild(this.renderer.domElement)

    this.scene = new THREE.Scene()
    this.scene.fog = new THREE.FogExp2(0x0b1a1d, 0.028)
    this.camera = new THREE.PerspectiveCamera(42, 1, 0.1, 200)
    this.camera.position.set(6, 4, 8)

    this.hemi = new THREE.HemisphereLight(0x9ffff0, 0x14201f, 1.25)
    this.scene.add(this.hemi)
    this.sun = new THREE.DirectionalLight(0xffe9c4, 2.2)
    this.sun.position.set(7, 12, 6)
    this.sun.castShadow = true
    this.sun.shadow.mapSize.set(2048, 2048)
    this.sun.shadow.camera.left = -16
    this.sun.shadow.camera.right = 16
    this.sun.shadow.camera.top = 16
    this.sun.shadow.camera.bottom = -16
    this.sun.shadow.camera.near = 1
    this.sun.shadow.camera.far = 40
    this.sun.shadow.bias = -0.0009
    this.scene.add(this.sun)
    this.rim = new THREE.DirectionalLight(0x62ffd0, 0.9)
    this.rim.position.set(-8, 5, -7)
    this.scene.add(this.rim)
    this.arenaGlow = new THREE.PointLight(0xff8a5c, 0, 20, 2)
    this.arenaGlow.position.set(0, 3, 0)
    this.scene.add(this.arenaGlow)

    this.buildHabitat()
    this.buildArena()
    this.setMode('habitat', true)
    this.bindPointer()
    this.resize()
    window.addEventListener('resize', () => this.resize())

    this.clock = new THREE.Clock()
    this.raf = requestAnimationFrame(() => this.loop())
  }

  buildHabitat() {
    const g = new THREE.Group()
    this.habitat = g
    this.scene.add(g)

    g.add(skyMesh('#071426', '#1c4d4b', '#081416'))

    const groundTex = groundTexture('habitat')
    const ground = new THREE.Mesh(
      new THREE.CircleGeometry(15, 72),
      new THREE.MeshStandardMaterial({ map: groundTex, color: 0xffffff, roughness: 0.95, metalness: 0 })
    )
    ground.rotation.x = -Math.PI / 2
    ground.receiveShadow = true
    g.add(ground)

    const under = new THREE.Mesh(
      new THREE.CylinderGeometry(15.2, 15.8, 1.4, 72),
      new THREE.MeshStandardMaterial({ color: '#0d2124', roughness: 0.9, flatShading: true })
    )
    under.position.y = -0.71
    under.receiveShadow = true
    g.add(under)

    // luminous rim
    const rim = new THREE.Mesh(
      new THREE.TorusGeometry(14.6, 0.035, 6, 120),
      new THREE.MeshBasicMaterial({ color: '#67ffc8' })
    )
    rim.rotation.x = -Math.PI / 2
    rim.position.y = 0.02
    g.add(rim)

    // distant moon
    const moon = new THREE.Mesh(new THREE.SphereGeometry(3.2, 24, 16), new THREE.MeshBasicMaterial({ color: '#cfe9d3' }))
    moon.position.set(-22, 17, -34)
    g.add(moon)
    const moonGlow = new THREE.Mesh(new THREE.SphereGeometry(4.4, 20, 14), new THREE.MeshBasicMaterial({ color: '#6dffc9', transparent: true, opacity: 0.12, blending: THREE.AdditiveBlending, depthWrite: false }))
    moonGlow.position.copy(moon.position)
    g.add(moonGlow)

    for (let i = 0; i < 26; i++) {
      const a = -0.2 + Math.random() * Math.PI * 1.4
      const r = 11 + Math.random() * 9
      const x = Math.cos(a) * r
      const z = Math.sin(a) * r
      if (Math.abs(x) < 11 && z > -14) {
        if (Math.random() < 0.55) g.add(tree(x, z, 0.8 + Math.random() * 1.1, ['#174a44', '#1c5b4e', '#123e40'][i % 3]))
        else g.add(crystal(x, z, 0.8 + Math.random() * 1.4, ['#7dffd0', '#9a8cff', '#ffd27a'][i % 3]))
      }
    }
    for (let i = 0; i < 18; i++) {
      const a = Math.random() * Math.PI * 2
      const r = 3.6 + Math.random() * 9.4
      g.add(mushroom(Math.cos(a) * r, Math.sin(a) * r, 0.6 + Math.random() * 1.2, ['#8dffbe', '#ffb3d9', '#9ad7ff', '#ffe28a'][i % 4]))
    }
    for (let i = 0; i < 14; i++) {
      const a = Math.random() * Math.PI * 2
      const r = 3.2 + Math.random() * 10
      const rock = new THREE.Mesh(
        new THREE.DodecahedronGeometry(0.18 + Math.random() * 0.5, 0),
        new THREE.MeshStandardMaterial({ color: '#24413e', roughness: 0.95, flatShading: true })
      )
      rock.position.set(Math.cos(a) * r, 0.14, Math.sin(a) * r)
      rock.rotation.set(Math.random(), Math.random(), Math.random())
      rock.castShadow = true
      g.add(rock)
    }

    // central ceremonial rings
    for (const [r, op] of [[3.1, 0.3], [5.4, 0.16], [8.1, 0.1]]) {
      const ring = new THREE.Mesh(
        new THREE.RingGeometry(r - 0.025, r + 0.025, 96),
        new THREE.MeshBasicMaterial({ color: '#64ffc4', transparent: true, opacity: op, side: THREE.DoubleSide })
      )
      ring.rotation.x = -Math.PI / 2
      ring.position.y = 0.025
      g.add(ring)
    }

    this.spores = sporeField(180, '#9dffd7', 15, 5.5, 0.075)
    g.add(this.spores)
    this.fireflies = sporeField(60, '#ffd27a', 11, 3.2, 0.12)
    g.add(this.fireflies)

    // floating islets
    for (let i = 0; i < 5; i++) {
      const isle = new THREE.Group()
      const rock = new THREE.Mesh(
        new THREE.DodecahedronGeometry(0.5 + Math.random() * 0.6, 0),
        new THREE.MeshStandardMaterial({ color: '#1a3838', roughness: 0.9, flatShading: true })
      )
      rock.scale.y = 1.6
      isle.add(rock)
      const tuft = new THREE.Mesh(new THREE.IcosahedronGeometry(0.35, 0), new THREE.MeshStandardMaterial({ color: '#2b6b58', flatShading: true }))
      tuft.position.y = 0.5
      isle.add(tuft)
      const a = Math.random() * Math.PI * 2
      isle.position.set(Math.cos(a) * (8 + Math.random() * 6), 3.2 + Math.random() * 3.5, Math.sin(a) * (8 + Math.random() * 6))
      isle.userData.baseY = isle.position.y
      isle.userData.phase = Math.random() * 10
      g.add(isle)
      if (!this.isles) this.isles = []
      this.isles.push(isle)
    }

    this.selectionRing = new THREE.Mesh(
      new THREE.TorusGeometry(0.72, 0.028, 6, 64),
      new THREE.MeshBasicMaterial({ color: '#d8ff5f' })
    )
    this.selectionRing.rotation.x = -Math.PI / 2
    this.selectionRing.position.y = 0.03
    this.selectionRing.visible = false
    g.add(this.selectionRing)
  }

  buildArena() {
    const g = new THREE.Group()
    this.arena = g
    g.visible = false
    this.scene.add(g)

    g.add(skyMesh('#120b1c', '#4a2238', '#100a14'))

    const groundTex = groundTexture('arena')
    const arena = new THREE.Mesh(
      new THREE.CylinderGeometry(11, 11.8, 1.1, 64),
      new THREE.MeshStandardMaterial({ map: groundTex, roughness: 0.9, metalness: 0.05 })
    )
    arena.position.y = -0.56
    arena.receiveShadow = true
    g.add(arena)

    const rim = new THREE.Mesh(new THREE.TorusGeometry(10.9, 0.09, 8, 120), new THREE.MeshBasicMaterial({ color: '#ff8a5c' }))
    rim.rotation.x = -Math.PI / 2
    rim.position.y = 0.02
    g.add(rim)

    for (let i = 0; i < 9; i++) {
      const a = (i / 9) * Math.PI * 2
      const r = 10.2
      const pillar = new THREE.Group()
      const base = new THREE.Mesh(new THREE.CylinderGeometry(0.4, 0.55, 0.4, 6), new THREE.MeshStandardMaterial({ color: '#2a2130', roughness: 0.9, flatShading: true }))
      base.position.y = 0.2
      pillar.add(base)
      const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.32, 2.2, 6), new THREE.MeshStandardMaterial({ color: '#3a2e40', roughness: 0.8, flatShading: true }))
      shaft.position.y = 1.4
      shaft.castShadow = true
      pillar.add(shaft)
      const orb = new THREE.Mesh(new THREE.IcosahedronGeometry(0.24, 1), new THREE.MeshBasicMaterial({ color: i % 2 ? '#ffb46b' : '#ff5e8a' }))
      orb.position.y = 2.7
      pillar.add(orb)
      pillar.position.set(Math.cos(a) * r, 0, Math.sin(a) * r)
      g.add(pillar)
      pillar.userData.orb = orb
    }

    const beams = new THREE.Group()
    for (let i = 0; i < 4; i++) {
      const a = i * Math.PI / 2 + Math.PI / 4
      const beam = new THREE.Mesh(
        new THREE.CylinderGeometry(0.02, 0.5, 14, 6, 1, true),
        new THREE.MeshBasicMaterial({ color: i % 2 ? '#ff7a5c' : '#ffae6b', transparent: true, opacity: 0.055, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending })
      )
      beam.position.set(Math.cos(a) * 7, 6.9, Math.sin(a) * 7)
      beams.add(beam)
    }
    g.add(beams)
    this.arenaBeams = beams

    this.embers = sporeField(120, '#ff9a6b', 10, 5.5, 0.08)
    g.add(this.embers)
    const dust = sporeField(60, '#ffd7a8', 11, 2.4, 0.05)
    g.add(dust)

    this.p1Ring = new THREE.Mesh(new THREE.TorusGeometry(0.9, 0.03, 6, 48), new THREE.MeshBasicMaterial({ color: '#b9ff68' }))
    this.p1Ring.rotation.x = -Math.PI / 2
    this.p1Ring.position.set(-3.4, 0.035, 0)
    g.add(this.p1Ring)
    this.p2Ring = new THREE.Mesh(new THREE.TorusGeometry(0.9, 0.03, 6, 48), new THREE.MeshBasicMaterial({ color: '#ff6b8a' }))
    this.p2Ring.rotation.x = -Math.PI / 2
    this.p2Ring.position.set(3.4, 0.035, 0)
    g.add(this.p2Ring)
  }

  setMode(mode, instant = false) {
    this.mode = mode
    this.autoRotate = mode === 'habitat'
    if (mode === 'habitat') {
      this.habitat.visible = true
      this.arena.visible = false
      this.scene.fog.color.set(0x0b1a1d)
      this.scene.fog.density = 0.026
      this.sun.color.set(0xffe9c4)
      this.sun.intensity = 2.2
      this.rim.color.set(0x62ffd0)
      this.rim.intensity = 0.9
      this.hemi.color.set(0x9ffff0)
      this.hemi.intensity = 1.25
      this.arenaGlow.intensity = 0
      this.orbit = { yaw: 0.55, pitch: 0.34, radius: 10.5, targetY: 1.35 }
      if (!instant) this.orbit.yaw = this.orbitYaw ?? 0.55
      this.bindCamera = { yaw: this.orbit.yaw, pitch: this.orbit.pitch, radius: this.orbit.radius }
    } else {
      this.habitat.visible = false
      this.arena.visible = true
      this.scene.fog.color.set(0x180e16)
      this.scene.fog.density = 0.022
      this.sun.color.set(0xffc9a0)
      this.sun.intensity = 1.7
      this.rim.color.set(0xff7a8a)
      this.rim.intensity = 1.3
      this.hemi.color.set(0xffbfa0)
      this.hemi.intensity = 0.65
      this.arenaGlow.intensity = 22
      this.orbit = { yaw: 0, pitch: 0.2, radius: 11.6, targetY: 1.55 }
      this.bindCamera = { yaw: 0, pitch: 0.2, radius: 11.6 }
    }
    this.selectionRing.visible = false
    if (mode === 'habitat') this.refreshSelectionRing()
  }

  onModeChange

  setSelected(id) {
    this.selectedId = id
    this.refreshSelectionRing()
  }

  refreshSelectionRing() {
    const entry = this.creatures.get(this.selectedId)
    if (!entry || this.mode !== 'habitat') { this.selectionRing.visible = false; return }
    this.selectionRing.visible = true
    this.selectionRing.position.x = entry.root.position.x
    this.selectionRing.position.z = entry.root.position.z
  }

  addCreature(data, opts = {}) {
    const existing = this.creatures.get(data.id)
    if (existing) {
      this.removeCreature(data.id)
    }
    const root = buildCreature(data.genome)
    const scale = opts.scale ?? (0.9 + (data.genome.size[0] + data.genome.size[1]) * 0.09)
    root.scale.setScalar(scale)
    const pos = opts.position ?? [0, 0, 0]
    root.position.set(pos[0], 0, pos[2])
    root.rotation.y = opts.rotation ?? Math.random() * Math.PI * 2
    root.userData.creatureId = data.id
    this.habitat.add(root)
    const entry = {
      id: data.id, root, data,
      target: new THREE.Vector3(pos[0], 0, pos[2]),
      pause: Math.random() * 3,
      moving: 0,
      speed: 0.45 + Math.random() * 0.3,
      arena: false,
      phase: Math.random() * 10,
      portrait: Math.random() < 0.5,
    }
    this.creatures.set(data.id, entry)
    return entry
  }

  removeCreature(id) {
    const entry = this.creatures.get(id)
    if (!entry) return
    entry.root.userData.dispose?.()
    this.creatures.delete(id)
    if (this.selectedId === id) {
      this.selectedId = null
      this.selectionRing.visible = false
    }
  }

  clearCreatures() {
    for (const id of [...this.creatures.keys()]) this.removeCreature(id)
  }

  setWander(ids) {
    // put habitat creatures back into free roam
    for (const [id, entry] of this.creatures) {
      if (this.habitat.children.includes(entry.root)) {
        entry.arena = false
        entry.target.set((Math.random() - 0.5) * 7, 0, (Math.random() - 0.5) * 7)
      }
    }
    if (ids) this.roamingIds = new Set(ids)
    this.refreshSelectionRing()
  }

  enterArena(player, foe) {
    this.setMode('arena')
    this.clearCreatures()
    const pA = buildCreature(player.genome)
    const pB = buildCreature(foe.genome)
    pA.scale.setScalar(1.18 * (0.86 + (player.genome.size[0] + player.genome.size[1]) * 0.08))
    pB.scale.setScalar(1.18 * (0.86 + (foe.genome.size[0] + foe.genome.size[1]) * 0.08))
    pA.position.set(-3.3, 0, 0.4)
    pB.position.set(3.3, 0, 0.4)
    pA.rotation.y = Math.PI / 2 + 0.1
    pB.rotation.y = -Math.PI / 2 - 0.1
    pA.userData.creatureId = player.id
    pB.userData.creatureId = foe.id
    this.arena.add(pA, pB)
    this.fighters = { player: pA, foe: pB }
    this.playerStart = pA.position.clone()
    this.foeStart = pB.position.clone()
  }

  exitArena() {
    if (this.fighters) {
      this.fighters.player.userData.dispose()
      this.fighters.foe.userData.dispose()
      this.fighters = null
    }
    this.clearCreatures()
    this.setMode('habitat')
    this.setWander()
  }

  battleLunge(who, cb) {
    if (!this.fighters) return
    const mesh = who === 'player' ? this.fighters.player : this.fighters.foe
    const start = who === 'player' ? this.playerStart : this.foeStart
    const dir = who === 'player' ? 1.6 : -1.6
    const t0 = performance.now()
    const dur = 320
    const tick = () => {
      const k = (performance.now() - t0) / dur
      if (k >= 1) { mesh.position.x = start.x; if (cb) cb(); return }
      const e = Math.sin(Math.min(1, k) * Math.PI)
      mesh.position.x = start.x + dir * e
      mesh.position.z = start.z - (who === 'player' ? 0.8 : 0.8) * e
      requestAnimationFrame(tick)
    }
    tick()
  }

  hitReact(who) {
    if (!this.fighters) return
    const mesh = who === 'player' ? this.fighters.player : this.fighters.foe
    mesh.userData.flash?.('#ff7a6b', 0.22)
    this.shake(0.22)
    const start = mesh.position.clone()
    const t0 = performance.now()
    const tick = () => {
      const k = (performance.now() - t0) / 300
      if (k >= 1) { mesh.position.copy(start); return }
      const e = Math.sin(Math.min(1, k) * Math.PI) * 0.24
      mesh.position.x = start.x + (who === 'player' ? -e : e)
      requestAnimationFrame(tick)
    }
    tick()
    this.burst({ x: mesh.position.x, y: 1.05, z: mesh.position.z }, who === 'player' ? '#ff7a6b' : '#ffd27a', 26)
  }

  faint(who) {
    if (!this.fighters) return
    const mesh = who === 'player' ? this.fighters.player : this.fighters.foe
    const t0 = performance.now()
    const startY = mesh.rotation.z
    const tick = () => {
      const k = (performance.now() - t0) / 700
      if (k >= 1) return
      mesh.rotation.z = startY + (who === 'player' ? 1 : -1) * Math.min(1, k) * 1.1
      tickFall()
      requestAnimationFrame(tick)
    }
    const tickFall = () => {}
    tick()
  }

  burst(pos, color = '#ffffff', count = 24) {
    if (!this.bursts) {
      const geo = new THREE.BufferGeometry()
      const max = 600
      const positions = new Float32Array(max * 3)
      const colors = new Float32Array(max * 3)
      positions.fill(9999)
      geo.setAttribute('position', new THREE.BufferAttribute(positions, 3))
      geo.setAttribute('color', new THREE.BufferAttribute(colors, 3))
      const material = new THREE.PointsMaterial({ size: 0.16, vertexColors: true, transparent: true, opacity: 0.95, depthWrite: false, blending: THREE.AdditiveBlending })
      this.burstPoints = new THREE.Points(geo, material)
      this.burstPoints.frustumCulled = false
      this.scene.add(this.burstPoints)
      this.burstState = { next: 0, max, life: new Float32Array(max), vel: new Float32Array(max * 3), color: new Float32Array(max * 3) }
    }
    const st = this.burstState
    const c = new THREE.Color(color)
    for (let i = 0; i < count; i++) {
      const idx = st.next
      st.next = (st.next + 1) % st.max
      st.life[idx] = 0.6 + Math.random() * 0.5
      st.vel[idx * 3] = (Math.random() - 0.5) * 3.4
      st.vel[idx * 3 + 1] = Math.random() * 3.2 + 0.4
      st.vel[idx * 3 + 2] = (Math.random() - 0.5) * 2.6
      const pos3 = this.burstPoints.geometry.attributes.position.array
      pos3[idx * 3] = pos.x + (Math.random() - 0.5) * 0.3
      pos3[idx * 3 + 1] = pos.y + (Math.random() - 0.5) * 0.3
      pos3[idx * 3 + 2] = pos.z + (Math.random() - 0.5) * 0.3
      const col = this.burstPoints.geometry.attributes.color.array
      col[idx * 3] = c.r; col[idx * 3 + 1] = c.g; col[idx * 3 + 2] = c.b
    }
    this.burstPoints.geometry.attributes.position.needsUpdate = true
    this.burstPoints.geometry.attributes.color.needsUpdate = true
  }

  shake(amount) {
    this.shakeAmt = Math.min(0.5, this.shakeAmt + amount)
  }

  bindPointer() {
    const el = this.renderer.domElement
    const down = e => {
      this.pointer.down = true
      this.pointer.moved = 0
      this.pointer.x = e.clientX
      this.pointer.y = e.clientY
      this.pointer.lx = e.clientX
      this.pointer.ly = e.clientY
      this.autoRotate = false
      el.setPointerCapture?.(e.pointerId)
    }
    const move = e => {
      if (!this.pointer.down) return
      const dx = e.clientX - this.pointer.lx
      const dy = e.clientY - this.pointer.ly
      this.pointer.moved += Math.abs(dx) + Math.abs(dy)
      this.pointer.lx = e.clientX
      this.pointer.ly = e.clientY
      this.orbit.yaw -= dx * 0.006
      this.orbit.pitch = clamp(this.orbit.pitch + dy * 0.004, 0.02, 0.95)
    }
    const up = e => {
      if (!this.pointer.down) return
      this.pointer.down = false
      if (this.pointer.moved < 8) this.pickAt(e.clientX, e.clientY)
      if (this.mode === 'habitat') this.autoRotate = true
    }
    el.addEventListener('pointerdown', down)
    el.addEventListener('pointermove', move)
    el.addEventListener('pointerup', up)
    el.addEventListener('pointercancel', () => { this.pointer.down = false })
    el.addEventListener('wheel', e => {
      e.preventDefault()
      this.orbit.radius = clamp(this.orbit.radius + e.deltaY * 0.006, 6.5, 15)
    }, { passive: false })
  }

  pickAt(clientX, clientY) {
    if (this.mode !== 'habitat') return
    const rect = this.renderer.domElement.getBoundingClientRect()
    this.ndc.x = ((clientX - rect.left) / rect.width) * 2 - 1
    this.ndc.y = -((clientY - rect.top) / rect.height) * 2 + 1
    this.raycaster.setFromCamera(this.ndc, this.camera)
    const hits = this.raycaster.intersectObjects(this.habitat.children, true)
    for (const hit of hits) {
      let o = hit.object
      while (o && !o.userData.creatureId) o = o.parent
      if (o?.userData.creatureId) {
        this.hooks.onSelect?.(o.userData.creatureId)
        return
      }
    }
    this.hooks.onBackground?.()
  }

  resize() {
    const w = this.container.clientWidth || window.innerWidth
    const h = this.container.clientHeight || window.innerHeight
    this.renderer.setSize(w, h, false)
    this.camera.aspect = w / h
    this.camera.updateProjectionMatrix()
  }

  loop() {
    this.raf = requestAnimationFrame(() => this.loop())
    const dt = Math.min(0.05, this.clock.getDelta())
    this.time += dt

    if (this.mode === 'habitat') {
      this.updateHabitat(dt)
    } else {
      this.updateArena(dt)
    }

    this.updateParticles(dt)

    const orbit = this.orbit
    if (this.autoRotate && this.mode === 'habitat') {
      this.orbitYaw = (this.orbitYaw ?? orbit.yaw) + dt * 0.028
      orbit.yaw = this.orbitYaw
    }
    const target = new THREE.Vector3(0, orbit.targetY, 0)
    const dist = orbit.radius
    const camX = Math.sin(orbit.yaw) * Math.cos(orbit.pitch) * dist
    const camZ = Math.cos(orbit.yaw) * Math.cos(orbit.pitch) * dist
    const camY = orbit.targetY + Math.sin(orbit.pitch) * dist + 0.4
    this.camera.position.lerp(new THREE.Vector3(camX, camY, camZ), 0.08)
    if (this.shakeAmt > 0.001) {
      this.camera.position.x += (Math.random() - 0.5) * this.shakeAmt
      this.camera.position.y += (Math.random() - 0.5) * this.shakeAmt
      this.shakeAmt *= 0.9
    }
    this.camera.lookAt(target)

    // slow toggling details
    if (this.isles) for (const isle of this.isles) {
      isle.position.y = isle.userData.baseY + Math.sin(this.time * 0.5 + isle.userData.phase) * 0.25
      isle.rotation.y += dt * 0.05
    }
    if (this.arena.visible && this.arenaBeams) this.arenaBeams.rotation.y += dt * 0.03
    if (this.p1Ring) {
      const pulse = 1 + Math.sin(this.time * 2.4) * 0.07
      this.p1Ring.scale.setScalar(pulse)
      this.p2Ring.scale.setScalar(1 + Math.sin(this.time * 2.4 + 1.6) * 0.07)
    }

    this.renderer.render(this.scene, this.camera)
  }

  updateHabitat(dt) {
    const list = [...this.creatures.values()]
    for (const entry of list) {
      if (!this.habitat.children.includes(entry.root)) continue
      entry.pause -= dt
      const dx = entry.target.x - entry.root.position.x
      const dz = entry.target.z - entry.root.position.z
      const dist = Math.hypot(dx, dz)
      let moving = 0
      if (entry.pause <= 0) {
        if (dist < 0.25) {
          entry.pause = 2 + Math.random() * 5
          const a = Math.random() * Math.PI * 2
          const r = 1.5 + Math.random() * 4.8
          entry.target.set(Math.cos(a) * r, 0, Math.sin(a) * r)
        } else {
          moving = 1
          const step = Math.min(dist, entry.speed * dt)
          entry.root.position.x += (dx / dist) * step
          entry.root.position.z += (dz / dist) * step
          const want = Math.atan2(dx, dz)
          let diff = want - entry.root.rotation.y
          while (diff > Math.PI) diff -= Math.PI * 2
          while (diff < -Math.PI) diff += Math.PI * 2
          entry.root.rotation.y += diff * Math.min(1, dt * 4)
        }
      }
      entry.moving += (moving - entry.moving) * Math.min(1, dt * 5)
      entry.root.userData.update?.(dt, entry.moving)
      if (this.selectedId === entry.id) {
        this.selectionRing.position.x = entry.root.position.x
        this.selectionRing.position.z = entry.root.position.z
        this.selectionRing.scale.setScalar(1 + Math.sin(this.time * 3) * 0.06)
      }
    }
    // spore drift
    this.driftField(this.spores, dt, 0.25)
    this.driftField(this.fireflies, dt, 0.6)
  }

  updateArena(dt) {
    if (!this.fighters) return
    this.fighters.player.userData.update?.(dt, 0)
    this.fighters.foe.userData.update?.(dt, 0)
    this.driftField(this.embers, dt, 0.55)
  }

  driftField(points, dt, speed) {
    if (!points) return
    const arr = points.geometry.attributes.position.array
    const seeds = points.userData.seeds
    for (let i = 0; i < seeds.length; i++) {
      const s = seeds[i]
      arr[i * 3 + 1] += s.speed * dt * speed
      arr[i * 3] += Math.sin(this.time * 0.5 + s.phase) * dt * 0.12
      arr[i * 3 + 2] += Math.cos(this.time * 0.4 + s.phase) * dt * 0.1
      if (arr[i * 3 + 1] > 5.8) arr[i * 3 + 1] = 0.1
    }
    points.geometry.attributes.position.needsUpdate = true
  }

  updateParticles(dt) {
    if (!this.burstPoints) return
    const st = this.burstState
    const pos = this.burstPoints.geometry.attributes.position.array
    for (let i = 0; i < st.max; i++) {
      if (st.life[i] <= 0) continue
      st.life[i] -= dt
      if (st.life[i] <= 0) { pos[i * 3] = 9999; continue }
      st.vel[i * 3 + 1] -= 6 * dt
      pos[i * 3] += st.vel[i * 3] * dt
      pos[i * 3 + 1] += st.vel[i * 3 + 1] * dt
      pos[i * 3 + 2] += st.vel[i * 3 + 2] * dt
    }
    this.burstPoints.geometry.attributes.position.needsUpdate = true
  }

  destroy() {
    cancelAnimationFrame(this.raf)
    this.clearCreatures()
    this.renderer.dispose()
    this.container.innerHTML = ''
  }
}
